    @Override
    @Transactional
    public void saveOwner(Owner owner) throws DataAccessException {
        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
        if (owner.isNew()) {
            if (hasIdenticalOwner(owner)) {
